function colorFor(text) {
  var hash = 0;
  for (var i = 0; i < text.length; i++) {
    hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  }
  return 'hsl(' + (hash % 360) + ', 65%, 38%)';
}

// 'card.render' decorators receive (card, tileSnapshot) — a plain data
// summary of the already-built default tile, never a live DOM node — and
// return a patch the host applies for them. See
// docs/architecture/PLUGIN_SYSTEM.md "The card.render decorator contract".
ctx.api.middleware.register({
  name: 'color-tags',
  operations: ['card.render'],
  handler: async function(card, tileSnapshot) {
    var tags = (tileSnapshot && tileSnapshot.tagTexts) || [];
    if (!tags.length) return null;
    return {
      setStyleByIndex: {
        '.card-tag': tags.map(function(text) {
          return { background: colorFor(text), color: '#ffffff' };
        })
      }
    };
  }
});

ctx.logger.info('Card color tags active');
